import {acquisitionPanel} from './special-ui.js';
import {hudGraphic} from './classic-hud.js';
import * as E from './engine.js';
const paging=(kind,page,total,size)=>'<div class="catalog-pages"><button data-action="'+kind+'-page" data-index="'+(page-1)+'" '+(page<=0?'disabled':'')+'>← Anterior</button><span>'+Math.min(total,page*size+1)+'–'+Math.min(total,(page+1)*size)+' / '+total+'</span><button data-action="'+kind+'-page" data-index="'+(page+1)+'" '+((page+1)*size>=total?'disabled':'')+'>Siguiente →</button></div>';
export function buildCatalog(s,o,h){const {panelHead,img,esc,cost,icon}=h,categories={all:'Todo',production:'Recursos',military:'Ejército',defense:'Defensa',economy:'Economía',support:'Servicios',science:'Ciencia',infrastructure:'Infraestructura',decoration:'Decoración'},items=Object.values(E.BUILDINGS).filter(b=>b.id!=='hq'&&E.isBuildable(s,b)&&(o.archive||!b.archive)&&(o.category==='all'||b.kind===o.category)&&(!o.search||(b.name+' '+b.description).toLowerCase().includes(o.search.toLowerCase()))),size=18,page=Math.max(0,Math.min(o.page,Math.max(0,Math.ceil(items.length/size)-1))),list=items.slice(page*size,(page+1)*size);return panelHead('CONSTRUIR · MEJORAR · AMPLIAR','Instalaciones de tu base')+'<p class="intro">Selecciona un plano y marca su lugar. Los planos recuperados en operaciones aparecen en el catálogo original.</p><div class="chips"><button data-action="build-scope" data-type="native" class="'+(!o.archive?'active':'')+'">Auralis</button><button data-action="build-scope" data-type="archive" class="'+(o.archive?'active':'')+'">Archivo original y planos</button></div><label class="catalog-search">Buscar edificios<input id="build-search" placeholder="Nombre o función" value="'+esc(o.search)+'"></label><div class="chips shop-categories">'+Object.entries(categories).map(([key,label])=>'<button data-action="category" data-type="'+key+'" class="'+(o.category===key?'active':'')+'">'+hudGraphic(key)+'<span>'+label+'</span></button>').join('')+'</div>'+paging('build',page,items.length,size)+'<div class="cards">'+list.map(b=>{const locked=E.hqLevel(s)<b.hq||!!E.unlockMessage(s,b.id),count=b.id==='bridge'?s.world.bridges.length:s.buildings.filter(v=>v.type===b.id).length;return'<article class="card '+(locked?'locked':'')+'">'+img(b.id)+'<span class="card-level">'+(locked?'Com. '+E.unlockLevel(b.id)+' · Base '+b.hq:count+' / '+b.limit)+'</span><h3>'+esc(b.name)+'</h3><p>'+esc(b.description)+'</p>'+cost(b.cost)+'<button data-action="place" data-type="'+b.id+'" '+(locked||count>=b.limit?'disabled':'')+'>'+icon(locked?'shield':'plus')+(locked?'Com. '+E.unlockLevel(b.id)+' · Base '+b.hq:'Construir')+'</button></article>';}).join('')+'</div>'+paging('build',page,items.length,size)+'<button class="secondary wide" data-action="clear-terrain">Enviar trabajador a un recurso</button>';}
export function armyCatalog(s,o,h){const {panelHead,img,esc,cost,clock,fmt,icon}=h,categories={all:'Todo',infantry:'Infantería',range:'Especialistas',vehicle:'Vehículos',air:'Aeronaves',naval:'Armada'},matches=u=>o.category==='all'||(o.category==='naval'?u.waterborne:o.category==='air'?u.flying:o.category==='vehicle'?u.heavy&&!u.waterborne:o.category==='infantry'?['infantry','fortress'].includes(u.factory):['range','hospital','builders'].includes(u.factory)),items=Object.values(E.UNITS).filter(u=>(o.archive||!u.archive)&&!/worker/i.test(u.name)&&matches(u)&&(!o.search||(u.name+' '+E.BUILDINGS[u.factory].name).toLowerCase().includes(o.search.toLowerCase()))),size=o.archive?24:36,page=Math.max(0,Math.min(o.page,Math.max(0,Math.ceil(items.length/size)-1))),list=items.slice(page*size,(page+1)*size),queues=s.training.length?'<div class="section-label">Entrenamiento en curso</div><div class="queue">'+s.training.map(j=>'<div class="queue-item">'+img(j.type,j.level,true)+'<div><b>'+esc(E.UNITS[j.type].name)+'</b><div class="progress"><span style="width:'+Math.max(0,(s.time-j.started)/(j.ends-j.started)*100)+'%"></span></div><small>'+clock(j.ends-s.time)+'</small></div><button data-action="cancel-training" data-id="'+j.id+'" aria-label="Cancelar entrenamiento">'+icon('close')+'</button></div>').join('')+'</div>':'';return panelHead('ENTRENAR · INVESTIGAR · DESPLEGAR','Tu fuerza de combate.')+'<button class="wide" data-action="special-overview">Prototipos, fusión y maravillas</button><p>Cash local: '+E.specialState(s).credits+'. Se gana con metas y recompensas.</p><p>Capacidad '+E.population(s)+' / '+E.populationCap(s)+'. Las fábricas trabajan en paralelo. El catálogo incluye unidades de misión y facciones cuyos planos se recuperan en las operaciones.</p>'+queues+(s.study?'<div class="warning">Investigando '+esc(E.UNITS[s.study.type].name)+' · grado '+s.study.level+' · '+clock(s.study.ends-s.time)+'</div>':'')+'<div class="chips"><button data-action="army-scope" data-type="native" class="'+(!o.archive?'active':'')+'">Auralis</button><button data-action="army-scope" data-type="archive" class="'+(o.archive?'active':'')+'">Catálogo original</button></div><label class="catalog-search">Buscar tropas<input id="army-search" placeholder="Nombre o instalación" value="'+esc(o.search)+'"></label><div class="chips">'+Object.entries(categories).map(([key,label])=>'<button data-action="unit-category" data-type="'+key+'" class="'+(o.category===key?'active':'')+'">'+label+'</button>').join('')+'</div>'+paging('army',page,items.length,size)+'<div class="cards">'+list.map(u=>{const factory=E.availableFactory(s,u.id),locked=E.hqLevel(s)<u.hq||!factory||!E.isRecruitable(u)||!!E.unlockMessage(s,u.id,true),level=E.unitLevel(s,u.id),stats=E.unitStats(u.id,level),count=s.army.filter(a=>a.type===u.id).length;return'<article class="card '+(locked?'locked':'')+'">'+img(u.id,level,true)+'<span class="card-level">'+(locked?'Base '+u.hq:'Grado '+level)+'</span><h3>'+esc(u.name)+'</h3><small>'+fmt(stats.hp)+' vida · '+(u.heal?'cura '+u.heal:stats.damage+' daño')+' · '+u.pop+' plazas</small><p>'+(!E.isRecruitable(u)?(E.acquisitionRoutes(s,u.id).some(r=>r.kind!=='mission')?'Obtención especial · consulta su ficha':'Unidad de misión o rescate'):locked?'Com. '+E.unlockLevel(u.id,true)+' · '+esc(E.BUILDINGS[u.factory].name)+' '+u.required:count+' en la base · '+clock(u.time))+'</p>'+acquisitionPanel(s,u.id,{esc,cost},true)+(E.isRecruitable(u)?cost(u.cost):'')+'<button data-action="train" data-type="'+u.id+'" '+(locked?'disabled':'')+'>'+icon('plus')+' Entrenar</button><button data-action="unit-detail" data-type="'+u.id+'">Ficha y mejoras '+icon('arrow')+'</button></article>';}).join('')+'</div>'+paging('army',page,items.length,size);}
